package fable.hideseek.imba.item;
import fable.hideseek.imba.mask.MaskService;import fable.hideseek.imba.game.GameMessages;import net.fabricmc.fabric.api.event.player.UseItemCallback;import net.minecraft.block.Block;import net.minecraft.item.Item;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NbtCompound;import net.minecraft.registry.Registries;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.text.MutableText;import net.minecraft.text.Text;import net.minecraft.util.Identifier;import net.minecraft.util.TypedActionResult;
public final class ModelEquipHandler{private ModelEquipHandler(){}public static void register(){UseItemCallback.EVENT.register((player,world,hand)->{ItemStack stack=player.getStackInHand(hand);if(!isModelItem(stack))return TypedActionResult.pass(stack);if(!world.isClient&&player instanceof ServerPlayerEntity serverPlayer)equip(serverPlayer,stack);return TypedActionResult.success(stack,world.isClient);});}public static boolean isModelItem(ItemStack stack){return stack!=null&&!stack.isEmpty()&&stack.hasNbt()&&stack.getNbt().getBoolean("imba_model_item");}public static void equip(ServerPlayerEntity player,ItemStack stack){NbtCompound nbt=stack.getNbt();if(nbt==null)return;String kind=nbt.getString("imba_model_kind"),id=nbt.getString("imba_model_id");if(id.isEmpty())return;Identifier identifier=new Identifier(id);if("BLOCK".equalsIgnoreCase(kind)){Block block=Registries.BLOCK.get(identifier);MaskService.applyBlockMask(player,block);GameMessages.send(player,"mask.model_equipped",Text.literal("§aНадета модель: §f").append(block.getName()));}else if("ITEM".equalsIgnoreCase(kind)){Item item=Registries.ITEM.get(identifier);MaskService.applyItemMask(player,item);GameMessages.send(player,"mask.model_equipped",Text.literal("§aНадета модель: §f").append(item.getName()));}}public static ItemStack createModelItem(Item iconItem,String displayWord,String kind,Identifier maskId){ItemStack stack=new ItemStack(iconItem);MutableText name=Text.literal("Надеть модель ");if("BLOCK".equalsIgnoreCase(kind)&&Registries.BLOCK.containsId(maskId))name.append(Registries.BLOCK.get(maskId).getName());else if("ITEM".equalsIgnoreCase(kind)&&Registries.ITEM.containsId(maskId))name.append(Registries.ITEM.get(maskId).getName());else name.append(Text.literal(displayWord));stack.setCustomName(name);NbtCompound nbt=stack.getOrCreateNbt();nbt.putBoolean("imba_model_item",true);nbt.putString("imba_model_kind",kind);nbt.putString("imba_model_id",maskId.toString());return stack;}}
